import numpy as np
from scipy.optimize import minimize

def solve_n(n):
    # Objective function: Minimize -S2 (i.e., Maximize S2)
    def objective(a):
        return -np.sum(a**2)

    # Equality constraint: sum(a_i^3) = 0
    def constraint_eq(a):
        return np.sum(a**3)

    # Inequality constraint: a_i <= 2/sqrt(n) => (2/sqrt(n)) - a_i >= 0
    def constraint_ineq(a):
        limit = 2.0 / np.sqrt(n)
        return limit - a

    constraints = [
        {'type': 'eq', 'fun': constraint_eq},
        {'type': 'ineq', 'fun': constraint_ineq}
    ]

    # Define multiple initial guesses based on boundary conditions
    guesses = []

    if n == 2:
        # Analytical solution candidate: a1 = 2/sqrt(2), a2 = -2/sqrt(2)
        g1 = np.array([2.0/np.sqrt(n), -2.0/np.sqrt(n)])
        guesses.append(g1)

        # Start near origin
        guesses.append(np.array([0.1, 0.1]))

    else:
        # For n=3, 4, try guesses where components are near the limit, distributed around 0
        limit = 2.0 / np.sqrt(n)

        # Guess 1: Some positive, some negative, pushing towards limits (e.g., 2 elements at limit, others balanced)
        if n >= 3:
            g1 = np.full(n, limit / n) # Centered
            g1[0] = limit # Push one to limit
            g1[-1] = -limit / (n-1) * 2 # Balance with negative
            guesses.append(g1)

        # Guess 2: All zeros (to catch local minima)
        guesses.append(np.zeros(n))


    max_s2 = -np.inf

    for initial_guess in guesses:
        try:
            result = minimize(
                objective,
                initial_guess,
                method='SLSQP',
                constraints=constraints,
                options={'disp': False, 'ftol': 1e-6}
            )

            if result.success:
                s2 = -result.fun
                if s2 > max_s2:
                    max_s2 = s2

        except Exception as e:
            # print(f"Optimization failed for guess {initial_guess} with error: {e}")
            pass

    return max_s2

# Solve for n=2, 3, 4
n_values = [2, 3, 4]
results = {}
for n in n_values:
    print(f"--- Solving for n={n} ---")
    max_s2 = solve_n(n)
    if max_s2 is not None:
        # Rounding for clean reporting
        results[n] = round(max_s2, 6) 
        print(f"Max S2 for n={n}: {results[n]}")
    else:
        print(f"Failed to find solution for n={n}.")

print("\nFinal Results Dictionary:", results)

